import type { CancellationToken, Disposable, MessageConnection } from 'vscode-jsonrpc';

export interface Position {
  line: number;
  character: number;
}

export interface Range {
  start: Position;
  end: Position;
}

export interface Location {
  uri: string;
  range: Range;
}

export interface LocationLink {
  originSelectionRange?: Range;
  targetUri: string;
  targetRange: Range;
  targetSelectionRange: Range;
}

export interface TextEdit {
  range: Range;
  newText: string;
}

export interface MarkupContent {
  kind: 'plaintext' | 'markdown';
  value: string;
}

export interface Hover {
  contents: MarkupContent | string;
  range?: Range;
}

export interface CompletionItem {
  label: string;
  kind?: number;
  detail?: string;
  documentation?: string | MarkupContent;
  insertText?: string;
  insertTextFormat?: number;
  sortText?: string;
  filterText?: string;
  textEdit?: TextEdit;
  data?: unknown;
}

export interface CompletionList {
  isIncomplete: boolean;
  items: CompletionItem[];
}

export interface Diagnostic {
  range: Range;
  severity?: number;
  code?: string | number;
  source?: string;
  message: string;
}

export const TextDocumentSyncKind: {
  readonly None: 0;
  readonly Full: 1;
  readonly Incremental: 2;
};

export const CompletionItemKind: Record<string, number>;
export const DiagnosticSeverity: Record<string, number>;
export const MarkupKind: { readonly PlainText: 'plaintext'; readonly Markdown: 'markdown' };
export const InsertTextFormat: { readonly PlainText: 1; readonly Snippet: 2 };
export const SymbolKind: Record<string, number>;
export const FileChangeType: { readonly Created: 1; readonly Changed: 2; readonly Deleted: 3 };
export const ProposedFeatures: { readonly all: string[] };

export class TextDocument {
  readonly uri: string;
  readonly languageId: string;
  readonly version: number;
  readonly lineCount: number;
  static create(uri: string, languageId: string, version: number, content: string): TextDocument;
  getText(range?: Range): string;
  offsetAt(position: Position): number;
  positionAt(offset: number): Position;
}

export interface TextDocumentChangeEvent<T> {
  document: T;
}

export class TextDocuments<T extends TextDocument = TextDocument> {
  constructor(documentFactory?: typeof TextDocument);
  get(uri: string): T | undefined;
  all(): T[];
  keys(): string[];
  onDidOpen(listener: (e: TextDocumentChangeEvent<T>) => void): Disposable;
  onDidChangeContent(listener: (e: TextDocumentChangeEvent<T>) => void): Disposable;
  onDidClose(listener: (e: TextDocumentChangeEvent<T>) => void): Disposable;
  onDidSave(listener: (e: TextDocumentChangeEvent<T>) => void): Disposable;
  listen(connection: Connection): void;
}

export interface TextDocumentPositionParams {
  textDocument: { uri: string };
  position: Position;
}

export interface CompletionParams extends TextDocumentPositionParams {
  context?: { triggerKind: number; triggerCharacter?: string };
}

export interface InitializeParams {
  processId: number | null;
  rootUri: string | null;
  workspaceFolders?: Array<{ uri: string; name: string }> | null;
  initializationOptions?: unknown;
  capabilities?: unknown;
}

export interface InitializeResult {
  capabilities: Record<string, unknown>;
}

export interface Connection {
  console: {
    log(msg: unknown): void;
    info(msg: unknown): void;
    warn(msg: unknown): void;
    error(msg: unknown): void;
  };
  listen(): void;
  dispose(): void;
  onInitialize(handler: (params: InitializeParams, token: CancellationToken) => InitializeResult | Promise<InitializeResult>): void;
  onInitialized(handler: (params: unknown) => void): void;
  onShutdown(handler: () => void | Promise<void>): void;
  onExit(handler: () => void): void;
  onDidOpenTextDocument(handler: (params: { textDocument: { uri: string; languageId: string; version: number; text: string } }) => void): Disposable;
  onDidChangeTextDocument(handler: (params: { textDocument: { uri: string; version: number }; contentChanges: Array<{ range?: Range; text: string }> }) => void): Disposable;
  onDidSaveTextDocument(handler: (params: { textDocument: { uri: string } }) => void): Disposable;
  onDidCloseTextDocument(handler: (params: { textDocument: { uri: string } }) => void): Disposable;
  onDidChangeConfiguration(handler: (params: { settings: unknown }) => void): Disposable;
  onDidChangeWatchedFiles(handler: (params: { changes: Array<{ uri: string; type: number }> }) => void): Disposable;
  onDefinition(handler: (params: TextDocumentPositionParams, token: CancellationToken) => Location | Location[] | LocationLink[] | null | undefined | Promise<Location | Location[] | LocationLink[] | null | undefined>): Disposable;
  onCompletion(handler: (params: CompletionParams, token: CancellationToken) => CompletionItem[] | CompletionList | null | undefined | Promise<CompletionItem[] | CompletionList | null | undefined>): Disposable;
  onCompletionResolve(handler: (item: CompletionItem, token: CancellationToken) => CompletionItem | Promise<CompletionItem>): Disposable;
  onHover(handler: (params: TextDocumentPositionParams, token: CancellationToken) => Hover | null | undefined | Promise<Hover | null | undefined>): Disposable;
  onDocumentSymbol(handler: (params: { textDocument: { uri: string } }, token: CancellationToken) => unknown[]): Disposable;
  onSignatureHelp(handler: (params: TextDocumentPositionParams, token: CancellationToken) => unknown): Disposable;
  onRequest<P = unknown, R = unknown>(method: string, handler: (params: P, token: CancellationToken) => R | Promise<R>): Disposable;
  onNotification<P = unknown>(method: string, handler: (params: P) => void | Promise<void>): Disposable;
  sendRequest<R = unknown>(method: string, params?: unknown): Promise<R>;
  sendNotification(method: string, params?: unknown): Promise<void>;
  sendDiagnostics(params: { uri: string; diagnostics: Diagnostic[] }): Promise<void>;
}

export function createConnection(
  inputOrFeatures?: unknown,
  output?: NodeJS.WritableStream | MessageConnection,
): Connection;
